'use client';

import { useActionState } from 'react';

type ContactFormState = {
  message: string;
};

const initialState: ContactFormState = {
  message: '',
};

async function submitContactForm(
  _prevState: ContactFormState,
  formData: FormData
): Promise<ContactFormState> {
  'use server';

  const name = formData.get('name') as string | null;
  const email = formData.get('email') as string | null;
  const message = formData.get('message') as string | null;

  // JavaScript validation - check that all fields are provided
  if (!name || typeof name !== 'string' || name.trim() === '') {
    return { message: 'Name is required.' };
  }
  if (!email || typeof email !== 'string' || email.trim() === '') {
    return { message: 'Email is required.' };
  }
  if (!message || typeof message !== 'string' || message.trim() === '') {
    return { message: 'Message is required.' };
  }

  // Simulate saving the contact message
  console.log('Contact message received:', { name: name.trim(), email: email.trim(), message: message.trim() });

  return { message: 'Thank you! Your message has been sent.' };
}

export default function ContactForm() {
  const [state, formAction, pending] = useActionState(submitContactForm, initialState);

  return (
    <div>
      <h2>Contact Us</h2>
      <form action={formAction}>
        <div>
          <label htmlFor="name">Name</label>
          <input id="name" name="name" type="text" placeholder="Your name" required />
        </div>
        <div>
          <label htmlFor="email">Email</label>
          <input id="email" name="email" type="email" placeholder="your@email.com" required />
        </div>
        <div>
          <label htmlFor="message">Message</label>
          <textarea id="message" name="message" placeholder="Your message" required rows={5} />
        </div>
        <button type="submit" disabled={pending}>
          {pending ? 'Sending...' : 'Send Message'}
        </button>
        {state?.message && (
          <p aria-live="polite">{state.message}</p>
        )}
      </form>
    </div>
  );
}

